const Contracts = Type.Module({
});


export class BaseMintProxyMintProxyMint {
  public Script: Script
  constructor(
    proxyPolicyId: PolicyId,
    trace?: boolean = false,
  ) {
    this.Script = cborToScript(
      applyParamsToScript(
        trace
          ?
          ""
          :
          "",
        Type.Tuple([
          PolicyId,
        ]),
        [
          proxyPolicyId,
        ],
      ),
      "PlutusV3"
    );
  }
}
